"use client";

import { useId, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";

import { BlockFrame } from "../parts/block-frame";
import { LOGIN_VARIANTS, type LoginVariant } from "./login/data";
import { VariantBody } from "./login/variant-body";

/**
 * Sign-in and sign-up in five layouts behind one switch: an emailed code,
 * a centred password form, a split screen, an immersive backdrop and sign up.
 * Every form validates inline and only pretends to send.
 */
export function Login({ className }: { className?: string }) {
  const titleId = useId();
  const [variant, setVariant] = useState<LoginVariant>("code");

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Sign in
        </h2>
        <div className="-mx-1 max-w-full scroll-fade-effect-x scrollbar-none overflow-x-auto px-1 py-1">
          <SegmentedControl aria-label="Layout" options={LOGIN_VARIANTS} value={variant} onValueChange={setVariant} />
        </div>
      </header>
      <div key={variant}>
        <VariantBody variant={variant} />
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** The code the demo inbox "received". Any other six digits are refused. */
export const SAMPLE_CODE = "204816";

/** The sign-in layouts a person can switch between. */
export type LoginVariant = "code" | "centred" | "split" | "immersive" | "signup";

/** The variant tabs, in the order they show. */
export const LOGIN_VARIANTS: { value: LoginVariant; label: string }[] = [
  { value: "code", label: "Email code" },
  { value: "centred", label: "Centred" },
  { value: "split", label: "Split" },
  { value: "immersive", label: "Immersive" },
  { value: "signup", label: "Sign up" },
];

"use client";

import type { LoginVariant } from "./data";
import { EmailCodeFlow } from "./email-code-flow";
import { ImmersiveBackdrop } from "./immersive-backdrop";
import { PasswordForm } from "./password-form";
import { SignUpForm } from "./sign-up-form";
import { SplitArt } from "./split-art";

/** The body of one sign-in variant. */
export function VariantBody({ variant }: { variant: LoginVariant }) {
  switch (variant) {
    case "code":
      return (
        <div className="mx-auto w-full max-w-sm p-6">
          <EmailCodeFlow />
        </div>
      );
    case "centred":
      return (
        <div className="p-6">
          <PasswordForm />
        </div>
      );
    case "split":
      return (
        <div className="grid @2xl:grid-cols-2">
          <div className="order-2 @2xl:order-1">
            <SplitArt />
          </div>
          <div className="order-1 p-6 @2xl:order-2 @2xl:p-8">
            <EmailCodeFlow title="Sign in to your clinic" />
          </div>
        </div>
      );
    case "immersive":
      return (
        <div className="relative isolate flex min-h-144 items-center justify-center p-4 @md:p-10">
          <ImmersiveBackdrop />
          <div className="w-full max-w-sm rounded-2xl border border-border bg-card p-6 shadow-lg">
            <EmailCodeFlow />
          </div>
        </div>
      );
    case "signup":
      return (
        <div className="mx-auto w-full max-w-md p-6">
          <SignUpForm />
        </div>
      );
  }
}

"use client";

import { useState } from "react";

import { Button } from "@/components/ui/button";

import { KeyIcon } from "../icons";
import { BusySpinner } from "../shared/busy-spinner";
import { EmailField } from "../shared/email-field";
import { OrDivider } from "../shared/or-divider";
import { type Provider, ProviderButtons } from "../shared/provider-buttons";
import { StepStage } from "../shared/step-stage";
import { useEmailEntry } from "../shared/use-email-entry";
import { useTimers } from "../shared/use-timers";
import { CodeStep } from "./code-step";
import { SignedIn } from "./signed-in";

type Step = "email" | "code" | "done";
const ORDER: Step[] = ["email", "code", "done"];

/**
 * Sign in with an emailed code: the email step, the six-digit code step and
 * the signed-in step, in one card that morphs its height between them.
 * Passkey and the two providers skip straight to signed in.
 */
export function EmailCodeFlow({ title = "Sign in to Fernhill" }: { title?: string }) {
  const entry = useEmailEntry();
  const { later, clear } = useTimers();
  const [step, setStep] = useState<Step>("email");
  const [direction, setDirection] = useState(1);
  const [busy, setBusy] = useState<"send" | "passkey" | Provider | null>(null);
  const [address, setAddress] = useState("");

  const go = (next: Step) => {
    setDirection(ORDER.indexOf(next) >= ORDER.indexOf(step) ? 1 : -1);
    setStep(next);
    setBusy(null);
  };

  const send = () => {
    const to = entry.attempt();
    if (!to) return;
    setBusy("send");
    setAddress(to);
    later(() => go("code"), 700);
  };

  const quick = (route: "passkey" | Provider, label: string) => {
    setBusy(route);
    setAddress(label);
    later(() => go("done"), 1100);
  };

  const restart = () => {
    clear();
    entry.reset();
    go("email");
  };

  return (
    <StepStage stepKey={step} direction={direction}>
      {step === "email" ? (
        <div className="flex flex-col gap-5">
          <div className="flex flex-col gap-1">
            <h3 className="text-lg font-semibold">{title}</h3>
            <p className="text-sm text-muted-foreground">We send a six-digit code to your work email. No password to remember.</p>
          </div>
          <form
            noValidate
            className="flex flex-col gap-2"
            onSubmit={(event) => {
              event.preventDefault();
              send();
            }}
          >
            <EmailField entry={entry} disabled={busy !== null} />
            <Button type="submit" disabled={busy !== null} aria-busy={busy === "send"} className="relative">
              <BusySpinner busy={busy === "send"} />
              Continue
            </Button>
          </form>
          <p aria-live="polite" className="sr-only">
            {busy === "send" ? "Sending your code" : busy === "passkey" ? "Waiting for your device" : ""}
          </p>
          <OrDivider />
          <div className="flex flex-col gap-2">
            <Button
              type="button"
              variant="secondary"
              disabled={busy !== null}
              aria-busy={busy === "passkey"}
              onClick={() => quick("passkey", "your passkey")}
            >
              <BusySpinner busy={busy === "passkey"} icon={<KeyIcon aria-hidden="true" className="size-4" />} />
              Sign in with a passkey
            </Button>
            <ProviderButtons
              busy={busy === "work" || busy === "sso" ? busy : null}
              disabled={busy !== null}
              onPick={(provider) => quick(provider, provider === "work" ? "your work account" : "single sign-on")}
            />
          </div>
        </div>
      ) : step === "code" ? (
        <CodeStep address={address} onBack={() => go("email")} onVerified={() => go("done")} />
      ) : (
        <SignedIn via={address} onSignOut={restart} />
      )}
    </StepStage>
  );
}

