import type { ReactNode } from "react";

import { LoaderIcon } from "../icons";

/**
 * The spinner of a button that keeps its label while it works. With `icon`,
 * the spinner takes the icon's place at the same size. Without one, it sits in
 * the button's leading padding, so the label stays centred and the button's
 * width never moves; that button needs `relative`.
 */
export function BusySpinner({ busy, icon }: { busy: boolean; icon?: ReactNode }) {
  const spinner = <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" />;
  if (icon !== undefined) return busy ? spinner : icon;
  return (
    <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 start-3 flex items-center">
      {busy ? spinner : null}
    </span>
  );
}

"use client";

import { useId } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import type { EmailEntry } from "./use-email-entry";

/** Props for a labelled email field that explains its own errors. */
export interface EmailFieldProps {
  entry: EmailEntry;
  label?: string;
  autoFocus?: boolean;
  disabled?: boolean;
}

/**
 * An email field with its label, an inline error under it, and a one-tap fix
 * when the domain looks misspelt. The hint says Enter again keeps the address.
 */
export function EmailField({ entry, label = "Work email", autoFocus, disabled }: EmailFieldProps) {
  const id = useId();
  const noteId = `${id}-note`;
  const note = entry.error ?? (entry.suggestion ? "suggestion" : null);

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-medium">
        {label}
      </label>
      <Input
        id={id}
        type="email"
        autoComplete="email"
        placeholder="name@yourclinic.org"
        autoFocus={autoFocus}
        disabled={disabled}
        value={entry.value}
        onChange={(event) => entry.setValue(event.target.value)}
        onBlur={entry.blur}
        aria-invalid={entry.error ? true : undefined}
        aria-describedby={note ? noteId : undefined}
      />
      <div id={noteId} aria-live="polite" className="min-h-5 text-sm">
        {entry.error ? <p className="text-destructive">{entry.error}</p> : null}
        {entry.suggestion ? (
          <p className="text-muted-foreground">
            Did you mean{" "}
            <Button type="button" variant="link" size="sm" onClick={entry.accept}>
              {entry.suggestion}
            </Button>
            ? Press Enter again to keep what you typed.
          </p>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";

import { checkEmail } from "./email-check";

/**
 * Holds a typed email address and decides whether a submit may go ahead.
 * A malformed address blocks. A likely typo blocks once and shows the fix;
 * a second submit sends the address as typed.
 */
export function useEmailEntry(initial = "") {
  const [value, setRawValue] = useState(initial);
  const [touched, setTouched] = useState(false);
  const [typoShown, setTypoShown] = useState(false);
  const check = checkEmail(value);

  const setValue = (next: string) => {
    setRawValue(next);
    setTypoShown(false);
  };

  /** Returns the address to send to, or null when the person must fix it first. */
  const attempt = (): string | null => {
    setTouched(true);
    if (check.state === "empty" || check.state === "invalid") return null;
    if (check.state === "typo" && !typoShown) {
      setTypoShown(true);
      return null;
    }
    return value.trim();
  };

  const error = touched ? (check.state === "empty" ? "Enter your work email." : check.state === "invalid" ? check.message : null) : null;
  const suggestion = check.state === "typo" && typoShown ? check.suggestion : null;

  return {
    value,
    setValue,
    error,
    suggestion,
    attempt,
    blur: () => {
      if (value.trim()) setTouched(true);
    },
    accept: () => {
      if (suggestion) setValue(suggestion);
    },
    reset: () => {
      setRawValue(initial);
      setTouched(false);
      setTypoShown(false);
    },
  };
}

/** The state and actions `useEmailEntry` returns. */
export type EmailEntry = ReturnType<typeof useEmailEntry>;

/** What a typed email address is: empty, malformed, likely misspelt, or fine. */
export type EmailCheck =
  | { state: "empty" }
  | { state: "invalid"; message: string }
  | { state: "typo"; suggestion: string }
  | { state: "ok" };

// Domains people mistype often, and the one they meant.
const DOMAIN_FIXES = new Map(Object.entries({
  "gmial.com": "gmail.com",
  "gmai.com": "gmail.com",
  "gamil.com": "gmail.com",
  "gmail.co": "gmail.com",
  "hotmial.com": "hotmail.com",
  "outlok.com": "outlook.com",
  "outlook.co": "outlook.com",
  "yaho.com": "yahoo.com",
  "icloud.co": "icloud.com",
  "fernhil.clinic": "fernhill.clinic",
  "fernhill.clinc": "fernhill.clinic",
}));

const TLD_FIXES = new Map(Object.entries({ con: "com", cmo: "com", ocm: "com", nte: "net", ogr: "org" }));

const WELL_FORMED = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/**
 * Reads a typed address. A well-formed address on a domain people often
 * mistype comes back with the address they most likely meant.
 */
export function checkEmail(raw: string): EmailCheck {
  const value = raw.trim();
  if (!value) return { state: "empty" };
  if (!value.includes("@")) return { state: "invalid", message: "Add the @ and the domain, such as name@clinic.org." };
  if (!WELL_FORMED.test(value)) return { state: "invalid", message: "Check the part after the @. It needs a domain such as clinic.org." };

  const at = value.lastIndexOf("@");
  const name = value.slice(0, at);
  const domain = value.slice(at + 1);
  const lower = domain.toLowerCase();
  const fixed = DOMAIN_FIXES.get(lower);
  if (fixed) return { state: "typo", suggestion: `${name}@${fixed}` };

  const dot = lower.lastIndexOf(".");
  const tld = TLD_FIXES.get(lower.slice(dot + 1));
  if (tld) return { state: "typo", suggestion: `${name}@${lower.slice(0, dot + 1)}${tld}` };
  return { state: "ok" };
}

/** A thin rule with a word in the middle, between two ways to sign in. */
export function OrDivider({ label = "or" }: { label?: string }) {
  return (
    <div className="flex items-center gap-3 text-xs text-muted-foreground">
      <span aria-hidden="true" className="h-px flex-1 bg-border" />
      {label}
      <span aria-hidden="true" className="h-px flex-1 bg-border" />
    </div>
  );
}

"use client";

import { Button } from "@/components/ui/button";

import { BuildingIcon, LoaderIcon, ShieldIcon } from "../icons";

/** A sign-in route that is not an email address. */
export type Provider = "work" | "sso";

const PROVIDERS: { id: Provider; label: string; Icon: typeof BuildingIcon }[] = [
  { id: "work", label: "Continue with work account", Icon: BuildingIcon },
  { id: "sso", label: "Continue with single sign-on", Icon: ShieldIcon },
];

/** Props for the provider buttons. `busy` names the provider that is opening. */
export interface ProviderButtonsProps {
  busy: Provider | null;
  disabled?: boolean;
  onPick: (provider: Provider) => void;
}

/** Two outline buttons for signing in through a work account or the clinic's single sign-on. */
export function ProviderButtons({ busy, disabled, onPick }: ProviderButtonsProps) {
  return (
    <div className="grid gap-2">
      {PROVIDERS.map(({ id, label, Icon }) => (
        <Button key={id} type="button" variant="outline" disabled={disabled || busy !== null} onClick={() => onPick(id)}>
          {busy === id ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : <Icon aria-hidden="true" className="size-4" />}
          {busy === id ? "Opening your account" : label}
        </Button>
      ))}
    </div>
  );
}

"use client";

import { AnimatePresence, motion, type Transition, useReducedMotion } from "motion/react";
import { type ReactNode, useLayoutEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

const SHELL: Transition = { type: "spring", stiffness: 420, damping: 40 };
const SLIDE: Transition = { type: "spring", stiffness: 520, damping: 46 };
const FADE: Transition = { duration: 0.15 };

/** Props for a stage that swaps one step for the next. */
export interface StepStageProps {
  /** Changes when the step changes, so the old step leaves and the new one enters. */
  stepKey: string;
  /** 1 when moving forward, -1 when moving back. The new step slides in from that side. */
  direction: number;
  children: ReactNode;
  className?: string;
}

/**
 * Shows one step at a time. The new step slides a short way in from the
 * direction of travel while the shell springs to its height. Under reduced
 * motion the steps fade and the height changes at once.
 */
export function StepStage({ stepKey, direction, children, className }: StepStageProps) {
  const reduce = useReducedMotion();
  const inner = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | "auto">("auto");

  useLayoutEffect(() => {
    const element = inner.current;
    if (!element) return;
    const observer = new ResizeObserver(() => setHeight(element.offsetHeight));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  const offset = reduce ? 0 : direction * 24;

  return (
    <motion.div
      animate={{ height }}
      initial={false}
      transition={reduce ? { duration: 0 } : SHELL}
      className={cn("relative -mx-1 overflow-hidden", className)}
    >
      <div ref={inner} className="p-1">
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.div
            key={stepKey}
            initial={{ opacity: 0, x: offset }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -offset }}
            transition={reduce ? FADE : SLIDE}
          >
            {children}
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

