import { useCallback, useEffect, useState } from "react";

/**
 * Counts down whole seconds from `start` each time `restart` runs, for a
 * resend link that waits before it can be used again.
 */
export function useCountdown(start: number) {
  const [left, setLeft] = useState(0);

  useEffect(() => {
    if (left <= 0) return;
    const timer = setTimeout(() => setLeft((value) => value - 1), 1000);
    return () => clearTimeout(timer);
  }, [left]);

  const restart = useCallback(() => setLeft(start), [start]);
  const stop = useCallback(() => setLeft(0), []);

  return { left, restart, stop };
}

