const STRENGTH = [
  { label: "Too short", fill: "bg-destructive" },
  { label: "Weak", fill: "bg-chart-5" },
  { label: "Fair", fill: "bg-chart-4" },
  { label: "Good", fill: "bg-chart-2" },
  { label: "Strong", fill: "bg-chart-2" },
];

/** Scores a password from 0 to 4 on length and the kinds of character it mixes. */
function scorePassword(value: string) {
  if (value.length < 8) return 0;
  const kinds = [/[a-z]/, /[A-Z]/, /\d/, /[^A-Za-z0-9]/].filter((pattern) => pattern.test(value)).length;
  return Math.min(4, (value.length >= 12 ? 2 : 1) + Math.max(0, kinds - 2));
}

