        </div>
      </div>
      <EmailField entry={entry} />
      <PasswordField
        label="Password"
        value={password}
        onChange={setPassword}
        autoComplete="new-password"
        error={tried && score === 0 ? "Use at least 8 characters." : null}
        hint={
          password ? (
            <div className="flex items-center gap-3">
              <div aria-hidden="true" className="grid flex-1 grid-cols-4 gap-1">
                {[1, 2, 3, 4].map((bar) => (
                  <span key={bar} className={cn("h-1 rounded-full transition-colors", bar <= score ? strength.fill : "bg-muted")} />
                ))}
              </div>
              <span className="text-xs text-muted-foreground">{strength.label}</span>
            </div>
          ) : (
            <p className="text-muted-foreground">At least 8 characters. Mix in capitals, digits or symbols.</p>
          )
        }
      />
      <label htmlFor={termsId} className="flex cursor-pointer items-start gap-2 text-sm">
        <Checkbox id={termsId} checked={terms} onCheckedChange={(value) => setTerms(value === true)} aria-invalid={termsError ? true : undefined} className="mt-0.5" />
        <span>I accept the terms of service and the data processing agreement.</span>
      </label>
      <p aria-live="polite" className="text-sm text-destructive empty:hidden">
        {termsError}
      </p>
      <Button type="submit" disabled={busy} aria-busy={busy} className="relative">
        <BusySpinner busy={busy} />
        Create account
      </Button>
      <p aria-live="polite" className="sr-only">
        {busy ? "Creating your account" : ""}
      </p>
    </form>
  );
}

